1	import { dockLabel, HEADING_COUNT, WORLD_STEPS_PER_SECOND } from "@pirate-sea-race/content";
2	import { defaultSimulationConfig, dockInReach, NOT_DOCKED, toTilePosition } from "@pirate-sea-race/simulation";
3	import { cssColor, slotColor, type GrappleSnapshot, type ObjectivesSnapshot, type ShipSnapshot, type StatusSnapshot } from "./matchView.js";
4	
5	export type ConnectionStatus = "connected" | "disconnected";
6	
7	export interface HudModel {
8	  readonly code: string;
9	  readonly protocolVersion: number;
10	  readonly custom: boolean;
11	  readonly status: ConnectionStatus;
12	  readonly selfId: string;
13	  /** Players in the match, including those out of sight. */
14	  readonly players: number;
15	  /** The ships the server sent: the player's own and those in sight. */
16	  readonly ships: readonly ShipSnapshot[];
17	  /** The world tick of the last patch. */
18	  readonly worldTick: number;
19	  /** This player's encounter status, once the server sent it. */
20	  readonly encounter: StatusSnapshot | undefined;
21	  /** The grapples in sight, or aimed at this player. */
22	  readonly grapples: readonly GrappleSnapshot[];
23	  /** This player's rubbings and gold, once the server sent them. */
24	  readonly objectives?: ObjectivesSnapshot | undefined;
25	}
26	
27	/** Whole seconds left until a world tick, rounded up; 0 once it has passed. */
28	export function secondsUntil(tick: number, worldTick: number): number {
29	  return Math.max(0, Math.ceil((tick - worldTick) / WORLD_STEPS_PER_SECOND));
30	}
31	
32	/** A duel's elapsed time as its marker shows it (§6): minutes and seconds since the duel began. */
33	export function elapsedText(startTick: number, worldTick: number): string {
34	  const seconds = Math.max(0, Math.floor((worldTick - startTick) / WORLD_STEPS_PER_SECOND));
35	  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
36	}
37	
38	const COMPASS = ["east", "south-east", "south", "south-west", "west", "north-west", "north", "north-east"] as const;
39	
40	/** The compass point (of eight) from one position toward another; y grows south. */
41	export function compassToward(from: { x: number; y: number }, to: { x: number; y: number }): (typeof COMPASS)[number] {
42	  const turns = Math.atan2(to.y - from.y, to.x - from.x) / (2 * Math.PI);
43	  return COMPASS[(Math.round(turns * 8) + 8) % 8]!;
44	}
45	
46	/** The compass point of a heading (of 64). */
47	export function compassOfHeading(heading: number): (typeof COMPASS)[number] {
48	  return COMPASS[Math.round((heading / HEADING_COUNT) * 8) % 8]!;
49	}
50	
51	export interface HudLine {
52	  readonly text: string;
53	  /** What the line says, for tests and styling. */
54	  readonly state: string;
55	  /** Seconds left, where the line counts down. */
56	  readonly seconds?: number;
57	}
58	
59	/**
60	 * The grapple (J, §6): aiming (this player's telegraph is out, with its aim), cooling down after a miss, not
61	 * available (in a duel or waiting to respawn), or ready.
62	 */
63	export function grappleLine(model: Pick<HudModel, "selfId" | "encounter" | "grapples" | "worldTick">): HudLine {
64	  const own = model.grapples.find((grapple) => grapple.attackerId === model.selfId);
65	  if (own !== undefined) return { text: `Grappling, aimed ${compassOfHeading(own.aim)}`, state: "aiming", seconds: secondsUntil(own.landTick, model.worldTick) };
66	  const status = model.encounter;
67	  if (status !== undefined && status.mode !== "sea") return { text: "", state: "unavailable" };
68	  const cooldown = status === undefined ? 0 : secondsUntil(status.cooldownUntil, model.worldTick);
69	  if (cooldown > 0) return { text: `J: grapple in ${cooldown} s`, state: "cooldown", seconds: cooldown };
70	  return { text: "J: grapple a ship ahead", state: "ready" };
71	}
72	
73	/** A grapple aimed at this player (§6: escape before it lands), with the side it comes from. */
74	export function incomingLine(model: Pick<HudModel, "selfId" | "grapples" | "ships" | "worldTick">): HudLine {
75	  const incoming = model.grapples.find((grapple) => grapple.defenderId === model.selfId);
76	  if (incoming === undefined) return { text: "", state: "none" };
77	  const own = model.ships.find((ship) => ship.id === model.selfId);
78	  const attacker = model.ships.find((ship) => ship.id === incoming.attackerId);
79	  // Without both ships, the aim still says where it comes from: from the opposite side of its direction.
80	  const from = own !== undefined && attacker !== undefined ? compassToward(own, attacker) : compassOfHeading(incoming.aim + HEADING_COUNT / 2);
81	  return { text: `Incoming grapple from the ${from}! Sail out of range or out of its aim`, state: from, seconds: secondsUntil(incoming.landTick, model.worldTick) };
82	}
83	
84	const PROTECTION_SOURCES: Record<string, string> = { spawn: "departure", win: "won a duel", draw: "drawn duel", respawn: "respawned" };
85	
86	/** Escape protection (§6): nobody can grapple this player until it runs out (or it grapples someone). */
87	export function protectionLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
88	  const status = model.encounter;
89	  if (status === undefined || status.protection === "") return { text: "", state: "none" };
90	  const seconds = secondsUntil(status.protectedUntil, model.worldTick);
91	  return { text: `Protected for ${seconds} s (${PROTECTION_SOURCES[status.protection] ?? status.protection})`, state: status.protection, seconds };
92	}
93	
94	/** The loser's wait out of the world (§6): 15 s from the end of the fight, then a dock. */
95	export function respawnLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
96	  const status = model.encounter;
97	  if (status === undefined || status.mode !== "respawning") return { text: "", state: "none" };
98	  const seconds = secondsUntil(status.respawnAt, model.worldTick);
99	  return { text: `Duel lost: respawning at a dock in ${seconds} s`, state: "respawning", seconds };
100	}
101	
102	const TYPE_NAMES: Readonly<Record<string, string>> = { sun: "Sun", moon: "Moon", tide: "Tide", storm: "Storm" };
103	
104	/** A rubbing type's name as the HUD writes it: "Sun". */
105	export function typeName(type: string): string {
106	  return TYPE_NAMES[type] ?? type;
107	}
108	
109	/** The rubbings a player holds, by name: "Sun, Moon", or "none yet". */
110	export function rubbingsText(types: readonly string[]): string {
111	  return types.length === 0 ? "none yet" : types.map(typeName).join(", ");
112	}
113	
114	/**
115	 * What the island the player is moored at still seals (§4), which the server sends only to players moored there:
116	 * "Palm Key holds: Sun, Sun", or that it holds nothing more. Empty at sea.
117	 */
118	export function islandLine(model: Pick<HudModel, "selfId" | "ships" | "objectives">): HudLine {
119	  const own = model.ships.find((ship) => ship.id === model.selfId);
120	  const objectives = model.objectives;
121	  if (own === undefined || own.dock === NOT_DOCKED || objectives === undefined) return { text: "", state: "none" };
122	  const island = defaultSimulationConfig.map.islands[defaultSimulationConfig.map.docks[own.dock]?.island ?? -1]?.name ?? "This island";
123	  if (objectives.islandTypes.length === 0) return { text: `${island} holds no more rubbings`, state: "empty" };
124	  return { text: `${island} holds: ${objectives.islandTypes.map(typeName).join(", ")}`, state: objectives.islandTypes.join(",") };
125	}
126	
127	/** A recovery cache at the dock the player is moored at (§12): its contents, which only a player moored there sees. */
128	export function cacheLine(model: Pick<HudModel, "objectives">): HudLine {
129	  const types = model.objectives?.cacheTypes ?? [];
130	  if (types.length === 0) return { text: "", state: "none" };
131	  return { text: `Recovery cache here: ${types.map(typeName).join(", ")}`, state: types.join(",") };
132	}
133	
134	/**
135	 * Holding E at a dock (§4, §12): the hold in progress with the seconds left, or what E would do here (the island's
136	 * rubbing first, then a cache's), or nothing.
137	 */
138	export function holdLine(model: Pick<HudModel, "objectives">): HudLine {
139	  const objectives = model.objectives;
140	  if (objectives === undefined) return { text: "", state: "none" };
141	  if (objectives.channel !== "") {
142	    const seconds = Math.max(0, Math.ceil((objectives.channelTotal - objectives.channelHeld) / WORLD_STEPS_PER_SECOND));
143	    const what = objectives.channel === "collect" ? `Collecting the ${typeName(objectives.channelType)} rubbing` : `Claiming the ${typeName(objectives.channelType)} rubbing from the cache`;
144	    return { text: `${what}: keep holding E, ${seconds} s left`, state: `${objectives.channel}:${objectives.channelType}`, seconds };
145	  }
146	  const [kind, type] = objectives.target.split(":");
147	  if (kind === "collect") return { text: `Hold E to collect the ${typeName(type!)} rubbing`, state: `ready:${objectives.target}` };
148	  if (kind === "claim") return { text: `Hold E to claim the ${typeName(type!)} rubbing from the cache`, state: `ready:${objectives.target}` };
149	  return { text: "", state: "none" };
150	}
151	
152	/** The hold's progress from 0 to 1, for the bar (0 without a hold). */
153	export function holdProgress(objectives: ObjectivesSnapshot | undefined): number {
154	  if (objectives === undefined || objectives.channel === "" || objectives.channelTotal === 0) return 0;
155	  return Math.min(1, objectives.channelHeld / objectives.channelTotal);
156	}
157	
158	/** The last finished hold: "Collected the Sun rubbing", or why it came to nothing. */
159	export function resultLine(model: Pick<HudModel, "objectives">): HudLine {
160	  const result = model.objectives?.channelResult ?? "";
161	  if (result === "") return { text: "", state: "none" };
162	  const [kind, detail] = result.split(":");
163	  if (kind === "collected") return { text: `Collected the ${typeName(detail!)} rubbing`, state: result };
164	  if (kind === "claimed") return { text: `Claimed the ${typeName(detail!)} rubbing from the cache`, state: result };
165	  return { text: "Someone else took that rubbing first", state: result };
166	}
167	
168	/**
169	 * The last duel's settlement (§4, §11), from this player's side: what was stolen and the gold that moved. The loser
170	 * sees what was taken; both see the gold change; a draw moves nothing.
171	 */
172	export function settlementLine(model: Pick<HudModel, "objectives">): HudLine {
173	  const objectives = model.objectives;
174	  if (objectives === undefined || objectives.settledRole === "") return { text: "", state: "none" };
175	  const gold = Math.abs(objectives.goldChange);
176	  const stolen = objectives.stolen === "" ? "" : typeName(objectives.stolen);
177	  switch (objectives.settledRole) {
178	    case "winner":
179	      if (stolen === "") return { text: gold > 0 ? `Duel won: +${gold} gold (they held nothing you lack)` : "Duel won: nothing to take", state: "winner" };
180	      return { text: `Duel won: you took the ${stolen} rubbing${gold > 0 ? ` and ${gold} gold` : ""}`, state: `winner:${objectives.stolen}` };
181	    case "loser":
182	      if (stolen === "") return { text: gold > 0 ? `Duel lost: -${gold} gold` : "Duel lost: nothing taken", state: "loser" };
183	      return { text: `Duel lost: they took your ${stolen} rubbing${gold > 0 ? ` and ${gold} gold` : ""}`, state: `loser:${objectives.stolen}` };
184	    default:
185	      return { text: "Duel drawn: nothing changed hands", state: "draw" };
186	  }
187	}
188	
189	/**
190	 * Who picked what the last duel's settlement stole (§4), for both fighters: "You chose Moon" (or "They chose Moon")
191	 * when the winner picked it, "Taken by default: Moon" when the deadline applied the default. Nothing when nothing moved.
192	 */
193	export function choiceLine(model: Pick<HudModel, "objectives">): HudLine {
194	  const objectives = model.objectives;
195	  if (objectives === undefined || objectives.stolen === "" || objectives.settledRole === "") return { text: "", state: "none" };
196	  const stolen = typeName(objectives.stolen);
197	  if (objectives.settledChoice === "default") return { text: `Taken by default: ${stolen}`, state: "default" };
198	  if (objectives.settledChoice !== "winner") return { text: "", state: "none" };
199	  return { text: objectives.settledRole === "winner" ? `You chose ${stolen}` : `They chose ${stolen}`, state: "winner" };
200	}
201	
202	/** One option of the winner's theft choice: its key (1, 2, …), its type and its label. */
203	export interface TheftOption {
204	  readonly key: string;
205	  readonly type: string;
206	  readonly label: string;
207	}
208	
209	/**
210	 * The winner's theft choice (§4), while it is open: the eligible types on keys 1, 2, … and the whole seconds left
211	 * before the default applies. Undefined for anyone else, or once settled.
212	 */
213	export function theftChoice(model: Pick<HudModel, "objectives" | "worldTick">): { options: TheftOption[]; seconds: number; duel: string } | undefined {
214	  const objectives = model.objectives;
215	  if (objectives === undefined || objectives.theftDuel === "" || objectives.theftOptions.length === 0) return undefined;
216	  return {
217	    duel: objectives.theftDuel,
218	    seconds: secondsUntil(objectives.theftDeadline, model.worldTick),
219	    options: objectives.theftOptions.map((type, index) => ({ key: String(index + 1), type, label: `${index + 1}: ${typeName(type)}` })),
220	  };
221	}
222	
223	/** A player's input to an open theft choice: a key (its `KeyboardEvent.code`) or a click on option `n` (1, 2, …). */
224	export type TheftInput = { readonly code: string } | { readonly option: number };
225	
226	/**
227	 * The type a key or a click picks in an open theft choice: Digit/Numpad `n`, or a click on option `n`, is the `n`th
228	 * option. Undefined when no choice is open or the input names no option.
229	 */
230	export function chosenTheftType(choice: Pick<NonNullable<ReturnType<typeof theftChoice>>, "options"> | undefined, input: TheftInput): string | undefined {
231	  if (choice === undefined) return undefined;
232	  const key = "code" in input ? /^(?:Digit|Numpad)([1-9])$/.exec(input.code)?.[1] : String(input.option);
233	  return key === undefined ? undefined : choice.options.find((option) => option.key === key)?.type;
234	}
235	
236	function writeLine(element: HTMLElement, line: HudLine): void {
237	  element.textContent = line.text;
238	  element.dataset["state"] = line.state;
239	  if (line.seconds === undefined) delete element.dataset["seconds"];
240	  else element.dataset["seconds"] = String(line.seconds);
241	}
242	
243	function field(root: ParentNode, id: string): HTMLElement {
244	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
245	  if (element === null) throw new Error(`missing HUD field ${id}`);
246	  return element;
247	}
248	
249	/** "Palm Key, south dock" when moored, "at sea" otherwise. */
250	export function dockText(dock: number): string {
251	  return dock === NOT_DOCKED ? "at sea" : dockLabel(defaultSimulationConfig.map, dock);
252	}
253	
254	/**
255	 * What the player can do about docking right now, by the simulation's own rule (`dockInReach`; speed does not matter):
256	 * nothing to say when moored or far from any dock; otherwise press E.
257	 */
258	export function dockHint(ship: Pick<ShipSnapshot, "x" | "y" | "dock">): string {
259	  if (ship.dock !== NOT_DOCKED) return "";
260	  const config = defaultSimulationConfig;
261	  const berth = dockInReach(config, ship.x, ship.y);
262	  return berth === undefined ? "" : `Press E to dock at ${dockLabel(config.map, berth.id)}`;
263	}
264	
265	/** Writes the match status and the latest authoritative (not interpolated) state of the visible ships. */
266	export function renderHud(root: ParentNode, model: HudModel): void {
267	  field(root, "hud-code").textContent = model.code;
268	  field(root, "hud-protocol").textContent = `v${model.protocolVersion}`;
269	  field(root, "hud-players").textContent = String(model.players);
270	  field(root, "hud-status").textContent = model.status;
271	  field(root, "hud-mode").textContent = model.custom ? "custom" : "standard";
272	  field(root, "hud-self").textContent = model.selfId;
273	  const own = model.ships.find((ship) => ship.id === model.selfId);
274	  const dock = field(root, "hud-dock");
275	  dock.textContent = own === undefined ? "" : dockText(own.dock);
276	  dock.dataset["dock"] = String(own?.dock ?? NOT_DOCKED);
277	  field(root, "hud-dock-hint").textContent = own === undefined ? "" : dockHint(own);
278	  writeLine(field(root, "hud-grapple"), grappleLine(model));
279	  writeLine(field(root, "hud-incoming"), incomingLine(model));
280	  writeLine(field(root, "hud-protection"), protectionLine(model));
281	  writeLine(field(root, "hud-respawn"), respawnLine(model));
282	  writeLine(field(root, "hud-island"), islandLine(model));
283	  writeLine(field(root, "hud-cache"), cacheLine(model));
284	  writeLine(field(root, "hud-hold"), holdLine(model));
285	  const bar = field(root, "hud-hold-progress");
286	  const progress = holdProgress(model.objectives);
287	  bar.hidden = model.objectives?.channel === "" || model.objectives === undefined;
288	  bar.style.setProperty("--progress", String(progress));
289	  bar.dataset["held"] = String(model.objectives?.channelHeld ?? 0);
290	  bar.dataset["total"] = String(model.objectives?.channelTotal ?? 0);
291	  writeLine(field(root, "hud-result"), resultLine(model));
292	
293	  const list = field(root, "positions");
294	  const items = model.ships.map((ship) => {
295	    const item = document.createElement("li");
296	    item.dataset["shipId"] = ship.id;
297	    item.dataset["slot"] = String(ship.slot);
298	    item.dataset["x"] = String(ship.x);
299	    item.dataset["y"] = String(ship.y);
300	    item.dataset["heading"] = String(ship.heading);
301	    item.dataset["speed"] = String(ship.speed);
302	    item.dataset["dock"] = String(ship.dock);
303	    const swatch = document.createElement("span");
304	    swatch.className = "swatch";
305	    swatch.style.background = cssColor(slotColor(ship.slot));
306	    const tile = toTilePosition(defaultSimulationConfig, ship.x, ship.y);
307	    const who = ship.id === model.selfId ? "you" : ship.id;
308	    item.append(swatch, `${who}: tile ${tile.tileX},${tile.tileY}, heading ${ship.heading}, speed ${ship.speed}`);
309	    return item;
310	  });
311	  list.replaceChildren(...items);
312	}
313	
314	/**
315	 * The purse, beside the game whether it shows the sea or the arena: gold, rubbings, the last duel's settlement and,
316	 * for a winner choosing, the theft choice with its countdown (keys 1 and 2, or a click).
317	 */
318	export function renderPurse(root: ParentNode, model: Pick<HudModel, "objectives" | "worldTick">): void {
319	  const objectives = model.objectives;
320	  const gold = field(root, "purse-gold");
321	  gold.textContent = objectives === undefined ? "" : String(objectives.gold);
322	  gold.dataset["gold"] = String(objectives?.gold ?? 0);
323	  const rubbings = field(root, "purse-rubbings");
324	  rubbings.textContent = objectives === undefined ? "" : rubbingsText(objectives.rubbings);
325	  rubbings.dataset["types"] = objectives?.rubbings.join(",") ?? "";
326	  writeLine(field(root, "purse-settlement"), settlementLine(model));
327	  const chooser = field(root, "purse-choice");
328	  writeLine(chooser, choiceLine(model));
329	  // The server's own ticks, for tests: when the settlement happened and when the choice window would have closed.
330	  chooser.dataset["settledAt"] = String(objectives?.settledAt ?? 0);
331	  chooser.dataset["deadline"] = String(objectives?.choiceDeadline ?? 0);
332	  const panel = field(root, "theft-choice");
333	  const choice = theftChoice(model);
334	  panel.hidden = choice === undefined;
335	  panel.dataset["duel"] = choice?.duel ?? "";
336	  writeLine(field(root, "theft-deadline"), choice === undefined ? { text: "", state: "none" } : { text: `${choice.seconds} s to choose, then the rarest is taken`, state: "open", seconds: choice.seconds });
337	  const buttons = field(root, "theft-options");
338	  const wanted = choice?.options.map((option) => option.type).join(",") ?? "";
339	  if (buttons.dataset["types"] !== wanted) {
340	    buttons.dataset["types"] = wanted;
341	    buttons.replaceChildren(
342	      ...(choice?.options ?? []).map((option) => {
343	        const button = document.createElement("button");
344	        button.type = "button";
345	        button.dataset["type"] = option.type;
346	        button.dataset["key"] = option.key;
347	        button.textContent = option.label;
348	        return button;
349	      }),
350	    );
351	  }
352	}
