19	
20	const INPUT_INTERVAL_MS = 1000 / 60;
21	
22	function element<T extends HTMLElement>(selector: string): T {
23	  const found = document.querySelector<T>(selector);
24	  if (found === null) throw new Error(`missing element ${selector}`);
25	  return found;
26	}
27	
28	const landing = element<HTMLElement>("#landing");
29	const matchSection = element<HTMLElement>("#match");
30	const createButton = element<HTMLButtonElement>("#create-match");
31	const joinForm = element<HTMLFormElement>("#join-form");
32	const joinButton = element<HTMLButtonElement>("#join-match");
33	const codeInput = element<HTMLInputElement>("#join-code");
34	const errorText = element<HTMLElement>("#join-error");
35	const duelSection = element<HTMLElement>("#duel");
36	const duelHud = element<HTMLElement>("#duel-hud");
37	const seaHud = element<HTMLElement>("#hud");
38	const duelButtons = [element<HTMLButtonElement>("#create-duel"), element<HTMLButtonElement>("#practice-duel"), element<HTMLButtonElement>("#join-duel")];
39	const duelCodeInput = element<HTMLInputElement>("#duel-code");
40	const duelErrorText = element<HTMLElement>("#duel-error");
41	const endpoint = serverEndpoint(window.location);
42	
43	element<HTMLElement>('[data-testid="landing-protocol"]').textContent = String(PROTOCOL_VERSION);
44	
45	createButton.addEventListener("click", () => void connect(() => createMatch(endpoint)));
46	joinForm.addEventListener("submit", (event) => {
47	  event.preventDefault();
48	  void connect(() => joinMatch(endpoint, codeInput.value));
49	});
50	
51	element<HTMLButtonElement>("#create-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, false)));
52	element<HTMLButtonElement>("#practice-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, true)));
53	element<HTMLFormElement>("#join-duel-form").addEventListener("submit", (event) => {
54	  event.preventDefault();
55	  void connectDuel(() => joinDuel(endpoint, duelCodeInput.value));
56	});
57	
58	async function connectDuel(open: () => Promise<DuelRoom>): Promise<void> {
59	  for (const button of duelButtons) button.disabled = true;
60	  duelErrorText.textContent = "";
61	  try {
62	    const room = await open();
63	    // Development only: `?rtt=80&jitter=20` delays this socket both ways (README). Vite drops this branch, and the
64	    // module it imports, from the production build.
65	    if (import.meta.env.DEV) {
66	      const { applyDevLatency, devLatencyFromQuery } = await import("./devLatency.js");
67	      const latency = devLatencyFromQuery(window.location.search);
68	      if (latency !== undefined) applyDevLatency(room, latency);
69	    }
70	    enterDuel(room);
71	  } catch (error) {
72	    const message = refusalMessage(error);
73	    duelErrorText.textContent = message === MATCH_UNAVAILABLE_MESSAGE ? DUEL_UNAVAILABLE_MESSAGE : message;
74	    for (const button of duelButtons) button.disabled = false;
75	  }
76	}
