78	/** The duel HUD's developer toggle drives whichever duel is showing. */
79	function wireHitboxToggle(current: () => DuelClient | undefined): void {
80	  const boxes = element<HTMLInputElement>("#show-boxes");
81	  boxes.addEventListener("change", () => {
82	    current()?.setShowBoxes(boxes.checked);
83	    boxes.blur();
84	  });
85	}
86	
87	function enterDuel(room: DuelRoom): void {
88	  landing.hidden = true;
89	  duelSection.hidden = false;
90	  const duel = new DuelClient(duelRoomTransport(room), duelHud);
91	  wireHitboxToggle(() => duel);
92	  const dummy = element<HTMLSelectElement>("#dummy-select");
93	  dummy.addEventListener("change", () => {
94	    duel.setDummy(dummy.value as DummyBehaviour);
95	    dummy.blur();
96	  });
97	  const dummyControl = element<HTMLElement>("#dummy-control");
98	  const showDummyControl = () => {
99	    dummyControl.hidden = room.state?.practice !== true;
100	  };
101	  showDummyControl();
102	  room.onStateChange(showDummyControl);
103	  startArena(element<HTMLElement>("#arena"), duel);
104	}
105	
106	async function connect(open: () => Promise<MatchRoom>): Promise<void> {
107	  setBusy(true);
108	  errorText.textContent = "";
109	  try {
110	    enterMatch(await open());
111	  } catch (error) {
112	    errorText.textContent = refusalMessage(error);
113	    setBusy(false);
114	  }
115	}
116	
117	function setBusy(busy: boolean): void {
118	  createButton.disabled = busy;
119	  joinButton.disabled = busy;
120	}
121	
