1	import { matchMaker } from "colyseus";
2	import { expect } from "vitest";
3	import { isNavigable, seaMap } from "@pirate-sea-race/content";
4	import type { MatchRoom } from "@pirate-sea-race/server";
5	import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
6	import { duelInput } from "@pirate-sea-race/simulation/duel";
7	import { Buttons } from "@pirate-sea-race/protocol";
8	import { HeadlessClient, sleep, type DuelScript, type HeadlessClientOptions, type Movement } from "@pirate-sea-race/test-tools";
9	
10	/**
11	 * What the duel-at-sea tests share: the open stretch of sea they sail on, a pair of players placed on it, and the
12	 * scripted fighters. Each test file starts its own server; tests in a file run at once, one match each.
13	 */
14	
15	/** The row three tiles south of the hub, which the map keeps clear for a hull 20 tiles either side of the hub. */
16	export const OPEN_ROW = seaMap.hub.tileY + 3;
17	export const HUB_X = seaMap.hub.tileX;
18	export const TILE = seaMap.subUnitsPerTile;
19	/** Headings of 64: east, south, west, north. */
20	export const EAST = 0;
21	export const SOUTH = 16;
22	export const WEST = 32;
23	export const NORTH = 48;
24	
25	/**
26	 * Collects a test's clients and has them leave when that test finishes (tests in a file run at once). When it
27	 * finishes, and again once every client has left, it checks each match room those clients were in: the room checked
28	 * `checkLedger` and its own invariant (no ship removed while the ledger counts its player in the match, and no ship
29	 * without such a player) after every world tick, and found no violation; and the ledger refused nothing the room asked.
30	 */
31	export function tracker(onTestFinished: (fn: () => Promise<void>) => void): (client: HeadlessClient) => void {
32	  const clients: HeadlessClient[] = [];
33	  const rooms = new Set<MatchRoom>();
34	  onTestFinished(async () => {
35	    const checked = [...rooms];
36	    await Promise.all(clients.map((client) => client.leave()));
37	    await sleep(150);
38	    for (const room of checked) expectRoomChecks(room);
39	  });
40	  return (client) => {
41	    clients.push(client);
42	    const room = roomOf(client);
43	    if (room !== undefined) rooms.add(room);
44	  };
45	}
46	
47	/**
48	 * The test source layout (the server's test-only setting): Palm Key (island 0) and Old Stones (2) seal two Suns each,
49	 * Ember Rock (1) and Mist Cay (3) two Moons each, so a test picks a type by the island it moors at.
50	 */
51	export const TEST_SOURCE_LAYOUT = [
52	  ["sun", "sun"],
53	  ["moon", "moon"],
54	  ["sun", "sun"],
55	  ["moon", "moon"],
56	] as const;
57	
58	/** A dock of the island that seals `type` in the test layout: Palm Key's west dock for Sun, Ember Rock's east for Moon. */
59	export function dockFor(type: "sun" | "moon", which = 0): (typeof seaMap.docks)[number] {
60	  const islands = TEST_SOURCE_LAYOUT.flatMap((types, island) => (types[0] === type ? [island] : []));
61	  return seaMap.docks.filter((dock) => islands.includes(dock.island))[which]!;
62	}
63	
64	/** Holding E with no throttle: moors at a dock in reach, and keeps holding to collect or claim there. */
65	export const HOLD_E: Movement = { moveX: 0, moveY: 0, buttons: Buttons.Interact };
66	
67	/**
68	 * Puts a client's ship on a dock's tile, moors it there and holds E until it holds `type` (a collection, or a claim
69	 * from a cache there), then lets go.
70	 */
71	export async function collectAt(client: HeadlessClient, endpoint: string, dock: { id: number; tileX: number; tileY: number }, type: string, timeoutMs = 15_000): Promise<void> {
72	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
73	  await client.holdUntil(HOLD_E, () => client.rubbings().includes(type), timeoutMs);
74	  expect(client.ship()?.dock).toBe(dock.id);
75	}
76	
77	/**
78	 * What `tracker` asserts of each match room, for files that clean up their own clients: the room checked
79	 * `checkLedger` and its own invariant after every world tick and found no violation, and the ledger refused nothing.
80	 */
81	export function expectRoomChecks(room: MatchRoom): void {
82	  expect(room.invariantViolations, `invariants of match ${room.state.code}`).toEqual([]);
83	  expect(room.ledgerRefusals, `ledger refusals in match ${room.state.code}`).toEqual([]);
84	}
85	
86	export function roomOf(client: HeadlessClient): MatchRoom {
87	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
88	}
89	
90	/** Resolves once `predicate` holds for the room itself (its ledger or rules state), polling; rejects after `timeoutMs`. */
91	export async function until(predicate: () => boolean, timeoutMs = 5000, what = "condition"): Promise<void> {
92	  const deadline = Date.now() + timeoutMs;
93	  while (!predicate()) {
94	    if (Date.now() > deadline) throw new Error(`${what} not met within ${timeoutMs} ms`);
95	    await sleep(10);
96	  }
97	}
98	
99	export interface Seat {
100	  readonly tileX: number;
101	  readonly tileY: number;
102	  readonly heading: number;
103	}
104	
105	/** Whether a hull can sail the straight line between two tile centres (and so the tiles between see each other). */
106	export function openWater(from: Seat, to: Seat): boolean {
107	  const a = tileCentre(defaultSimulationConfig, from.tileX, from.tileY);
108	  const b = tileCentre(defaultSimulationConfig, to.tileX, to.tileY);
109	  return isNavigable(seaMap, from.tileX, from.tileY) && hullPathIsClear(defaultSimulationConfig, a.x, a.y, b.x, b.y);
110	}
111	
112	/** Players in one match, created in order (the first creates it), then placed at rest on their seats. */
113	export async function playersAt(
114	  endpoint: string,
115	  seats: readonly Seat[],
116	  track: (client: HeadlessClient) => void,
117	  options: { readonly endpoints?: readonly string[]; readonly clients?: readonly HeadlessClientOptions[] } = {},
118	): Promise<HeadlessClient[]> {
119	  const clients: HeadlessClient[] = [];
120	  for (const [index, seat] of seats.entries()) {
121	    const via = options.endpoints?.[index] ?? endpoint;
122	    const client = index === 0 ? await HeadlessClient.create(via, options.clients?.[0]) : await HeadlessClient.join(via, clients[0]!.code, options.clients?.[index]);
123	    track(client);
124	    clients.push(client);
125	    expect(openWater(seat, seat)).toBe(true);
126	  }
127	  await clients[0]!.waitFor(() => clients[0]!.playerCount === seats.length);
128	  for (const [index, seat] of seats.entries()) await clients[index]!.placeShip(endpoint, seat);
129	  return clients;
130	}
131	
132	/**
133	 * The host (attacker) and the guest in grapple range on the open row, `apart` tiles apart around the hub: the host
134	 * west facing east, the guest east facing `guestHeading` (west by default, toward the host).
135	 */
136	export async function pairInRange(
137	  endpoint: string,
138	  track: (client: HeadlessClient) => void,
139	  options: {
140	    readonly apart?: number;
141	    readonly guestHeading?: number;
142	    readonly endpoints?: readonly string[];
143	    readonly clients?: readonly HeadlessClientOptions[];
144	  } = {},
145	): Promise<{ host: HeadlessClient; guest: HeadlessClient }> {
146	  const apart = options.apart ?? 6;
147	  const host: Seat = { tileX: HUB_X - Math.floor(apart / 2), tileY: OPEN_ROW, heading: EAST };
148	  const guest: Seat = { tileX: host.tileX + apart, tileY: OPEN_ROW, heading: options.guestHeading ?? WEST };
149	  expect(openWater(host, guest)).toBe(true);
150	  const [first, second] = await playersAt(endpoint, [host, guest], track, options);
151	  await first!.waitFor(() => first!.ship(second!.sessionId) !== undefined);
152	  return { host: first!, guest: second! };
153	}
154	
155	/** Grapples: the host taps J, and both fighters' duel reaches its countdown. */
156	export async function grapple(host: HeadlessClient, guest: HeadlessClient): Promise<void> {
157	  host.tapGrapple();
158	  for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "countdown", 3000);
159	}
160	
161	const R = duelInput("right");
162	const L = duelInput("left");
163	const K = duelInput("heavy");
164	
165	/**
166	 * A fighter who walks in, then swings a heavy every 50 frames and steps forward before each: from either side, the
167	 * mirror of the other side's (player one starts on the left). Against a fighter who stands still it wins by KO in
168	 * about 500 frames; played by both, the mirrored fight ends in a double KO.
169	 */
170	export function brawler(slot: 0 | 1): DuelScript {
171	  const toward = slot === 0 ? R : L;
172	  return (frame) => {
173	    if (frame < 30) return toward;
174	    const beat = (frame - 30) % 50;
175	    if (beat === 0) return K;
176	    return beat > 44 ? toward : 0;
177	  };
178	}
179	
180	/** The lobby a fighter sees, as plain values. */
181	export function lobbyOf(client: HeadlessClient): { phase: string; winner: number; reason: string } | undefined {
182	  const lobby = client.fighter.lobby;
183	  return lobby === undefined ? undefined : { phase: lobby.phase, winner: lobby.winner, reason: lobby.reason };
184	}
185	
186	/** The fighters' result, once both see it (the same in both). */
187	export async function resultOf(host: HeadlessClient, guest: HeadlessClient, timeoutMs = 20_000): Promise<{ phase: string; winner: number; reason: string }> {
188	  for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "over", timeoutMs);
189	  expect(lobbyOf(guest)).toEqual(lobbyOf(host));
190	  return lobbyOf(host)!;
191	}
192	
193	/** Every grapple and marker a client decoded from now on, as the patches arrive. */
194	export function recordSightings(client: HeadlessClient): { grapples: Set<string>; markers: number; duelLobbies: number } {
195	  const seen = { grapples: new Set<string>(), markers: 0, duelLobbies: 0 };
196	  client.room.onStateChange(() => {
197	    for (const grapple of client.grapples()) seen.grapples.add(`${grapple.attackerId}>${grapple.defenderId}`);
198	    seen.markers = Math.max(seen.markers, client.markers().length);
199	    seen.duelLobbies = Math.max(seen.duelLobbies, client.duelCount);
200	  });
201	  return seen;
202	}
203	
204	export function containsText(frame: Uint8Array, text: string): boolean {
205	  return Buffer.from(frame).includes(Buffer.from(text, "utf8"));
206	}
207

