584	  /**
585	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
586	   * the last tick and of duels the ledger has settled, then the events applied. The rules alone choose targets, land
587	   * or miss grapples, start fights and decide returns; the room moves ships and runs the duels.
588	   */
589	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
590	    const tick = this.simulation.worldTick;
591	    const endedBy = this.protectionEndedNext;
592	    this.protectionEndedNext = new Set();
593	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
594	      const gate = this.gates.get(ship.id);
595	      const duel = this.duelOfSession(ship.id);
596	      return {
597	        id: ship.id,
598	        mode: "ship",
599	        x: ship.x,
600	        y: ship.y,
601	        heading: ship.heading,
602	        connected: this.clients.get(ship.id) !== undefined,
603	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
604	        ready: duel?.machine.isReady(ship.id) === true,
605	        // §6: last tick's collection or cache claim ended this player's protection.
606	        protectionEndedBy: endedBy.has(ship.id) ? "collection" : null,
607	      };
608	    });
609	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });
610	    this.encounters = stepped.state;
611	    for (const event of stepped.events) this.apply(event);
612	    for (const duel of [...this.seaDuels.values()]) if (duel.removeAfterTick !== undefined && tick > duel.removeAfterTick) this.closeSeaDuel(duel);
613	  }
614	
615	  /**
616	   * The reports for this tick. A fight that ended since the last tick is reported to the ledger (unless a player's
617	   * leaving already decided it there) and its end to the rules, as the ledger recorded it. A duel the ledger has
618	   * settled (at once for a draw, a cancellation or a win with nothing to steal; otherwise at the winner's choice or the
619	   * deadline's default) gets its `settled` report, never before: only then do its players return.
620	   */
621	  private duelReports(tick: number): DuelReport[] {
622	    const reports: DuelReport[] = [];
623	    for (const duel of this.seaDuels.values()) {
624	      const outcome = duel.machine.outcome;
625	      if (outcome !== undefined && !duel.ended) {
626	        duel.ended = true;
627	        if (findDuel(this.ledger, duel.id)?.phase === "fighting") {
628	          const winner = outcome.winner === null ? null : duel.players[outcome.winner];
629	          // §12: both fighters forfeiting on the same frame cancels; a double KO or an exact tie is a draw.
630	          const result = winner !== null ? "win" : outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw";
631	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: result, ...(winner !== null ? { winner } : {}) }));
632	        }
633	        if (!duel.endedByRules) reports.push(this.endReport(duel, tick));
634	      }
635	      if (!duel.ended || duel.settled) continue;
636	      const settled = findDuel(this.ledger, duel.id);
637	      if (settled === undefined || settled.phase === "settled") {
638	        duel.settled = true;
639	        const endTick = this.encounters.duels.find((each) => each.id === duel.id)?.end?.tick ?? tick;
640	        reports.push({ kind: "settled", duelId: duel.id, tick: Math.min(tick, Math.max(endTick, settled?.settlement?.tick ?? tick)) });
641	      }
642	    }
643	    return reports;
644	  }
645	
646	  /** The end report of a fight, as the ledger recorded its result (a quit may have decided it there first). */
647	  private endReport(duel: SeaDuel, tick: number): DuelReport {
648	    const result = findDuel(this.ledger, duel.id)?.result;
649	    if (result?.outcome === "win" && result.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: result.winner };
650	    if (result !== null && result !== undefined) return { kind: "end", duelId: duel.id, tick, outcome: result.outcome === "draw" ? "draw" : "cancelled" };
651	    const outcome = duel.machine.outcome!;
652	    if (outcome.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: duel.players[outcome.winner] };
653	    return { kind: "end", duelId: duel.id, tick, outcome: outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw" };
654	  }
655	
656	  private apply(event: EncounterEvent): void {
657	    switch (event.kind) {
658	      case "duel-reserved":
659	        this.ledgerStep("reserveDuel", reserveDuel(this.ledger, { duelId: event.duelId, players: event.players, tick: event.tick }));
660	        this.openSeaDuel(event.duelId, event.players, event.x, event.y, event.tick);
661	        return;
662	      case "duel-started":
663	        this.seaDuels.get(event.duelId)?.machine.start();
664	        return;
665	      case "duel-forfeited":
666	      case "duel-cancelled": {
667	        const duel = this.seaDuels.get(event.duelId);
668	        if (findDuel(this.ledger, event.duelId)?.phase === "fighting") {
669	          const report = event.kind === "duel-cancelled" ? { outcome: "cancelled" as const } : { outcome: "win" as const, winner: event.winner };
670	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: event.duelId, tick: event.tick, ...report }));
671	        }
672	        if (duel === undefined) return;
673	        duel.endedByRules = true;
674	        duel.ended = true;
675	        if (event.kind === "duel-cancelled") duel.machine.end(null, "cancelled");
676	        else duel.machine.end(duel.players.indexOf(event.winner) as PlayerIndex, "forfeit");
677	        return;
678	      }
679	      case "duel-settled": {
680	        const duel = this.seaDuels.get(event.duelId);
681	        if (duel === undefined) return;
682	        duel.removeAfterTick = event.tick + DUEL_RESULT_TICKS;
683	        this.state.markers.delete(duel.key);
684	        return;
685	      }
686	      case "player-returned":
687	      case "player-respawned":
688	        if (!this.simulation.ships.some((ship) => ship.id === event.playerId)) return;
689	        this.simulation = returnShip(this.config, this.simulation, event.playerId, {
690	          x: event.x,
691	          y: event.y,
692	          dock: event.kind === "player-respawned" ? (event.dockId ?? NOT_DOCKED) : NOT_DOCKED,
693	        });
694	        return;
695	      case "report-refused":
696	        this.refusedReports++;
697	        return;
698	      default:
699	        // Attempts, protection and the loser's wait are mirrored from the rules' state.
700	        return;
701	    }
702	  }
703	
704	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
705	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
706	    // A winner who attacks again while the last result is still showing: that lobby goes now.
707	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
708	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
709	    const key = `d${this.nextDuelKey++}`;
710	    const lobby = new SeaDuelSchema();
711	    lobby.code = this.state.code;
712	    lobby.practice = false;
713	    this.state.duels.set(key, lobby);
714	    const machine = new DuelMachine({
715	      lobby,
716	      seed: this.tuning.random(0, 2 ** 32),
717	      start: "called",
718	      send: (sessionId, type, message) => this.clients.get(sessionId)?.send(type, message),
719	    });
720	    players.forEach((player, slot) => {
721	      machine.addSeat(player, slot as PlayerIndex);
722	      if (this.clients.get(player) === undefined) machine.drop(player);
723	    });
724	    // A player grappled while away counts as away from the duel from its start.
725	    for (const player of players) {
726	      const away = this.away.get(player);
727	      if (away !== undefined) away.duelAbsentSince = tick;
728	    }
729	    machine.beginCountdown();
730	    const marker = new DuelMarkerSchema();
731	    marker.x = x;
732	    marker.y = y;
733	    marker.startTick = tick;
734	    this.state.markers.set(key, marker);
735	    this.seaDuels.set(id, { id, key, players, lobby, machine, endedByRules: false, ended: false, settled: false, removeAfterTick: undefined });
736	  }
737	
738	  /**
739	   * §4 and §12's holds, one world tick: a connected player moored at a dock, out of any duel and holding E works on
740	   * E's target there (`interactTarget`). The same target as their hold continues it; another starts a new hold from
741	   * zero; no E, no mooring or no target cancels it (the ledger's rule: progress resets). Starting one ends protection
742	   * on the next tick.
743	   */
744	  private stepChannels(frame: number, tick: number): void {
745	    const held = this.heldPlayers();
746	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
747	    for (const player of this.ledger.players) {
748	      if (player.status !== "connected") continue;
749	      const id = player.id;
750	      const ship = ships.get(id);
751	      const gate = this.gates.get(id);
752	      const holding =
753	        ship !== undefined && gate !== undefined && ship.dock !== NOT_DOCKED && !held.has(id) && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0;
754	      const target = holding ? interactTarget(this.ledger, this.config.map, id, ship.dock) : undefined;
755	      if (target === undefined) {
756	        if (player.channel !== null) this.ledgerStep("cancelChannel", cancelChannel(this.ledger, { playerId: id, tick }));
757	        continue;
758	      }
759	      if (sameTarget(player.channel, target)) {
760	        const result = this.ledgerStep("progressChannel", progressChannel(this.ledger, { playerId: id, tick }));
761	        if (result.status === "collected" || result.status === "claimed" || result.status === "failed") {
762	          const notice = this.noticesOf(id);
763	          notice.channelResult = result.status === "failed" ? `failed:${result.failure}` : `${result.status}:${target.type}`;
764	          notice.channelResultAt = tick;
765	        }
766	        continue;
767	      }
768	      const started =
769	        target.kind === "collect"
770	          ? this.ledgerStep("startCollect", startCollect(this.ledger, { playerId: id, sourceId: target.sourceId, tick }))
771	          : this.ledgerStep("startCacheClaim", startCacheClaim(this.ledger, { playerId: id, cacheId: target.cacheId, rubbingId: target.rubbingId, tick }));
772	      if (started.ok) this.protectionEndedNext.add(id);
773	    }
774	  }
775	
776	  /** §4's theft choice from a client: the winner of a duel at sea, in its window, for an eligible type. */
777	  private receiveTheftChoice(sessionId: string, message: unknown): void {
778	    const frame = this.simulation.frame;
779	    const rate = this.choiceRate.get(sessionId) ?? { windowStart: frame, count: 0 };
780	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
781	      rate.windowStart = frame;
782	      rate.count = 0;
783	    }
784	    rate.count++;
785	    this.choiceRate.set(sessionId, rate);
786	    if (rate.count > MAX_CHOOSE_THEFT_PER_SECOND) return;
787	    const choice = validateChooseTheftMessage(message);
788	    if (choice === undefined) return;
789	    const duel = [...this.seaDuels.values()].find((each) => each.key === choice.duel && each.players.includes(sessionId));
790	    if (duel === undefined) return;
791	    // The ledger checks that this player won, the window is open and the type is eligible; otherwise nothing changes.
792	    const stepped = chooseTheft(this.ledger, { duelId: duel.id, playerId: sessionId, type: choice.type, tick: this.simulation.worldTick });
793	    this.ledger = stepped.state;
794	    this.noteSettlements();
795	  }
796	
797	  private noticesOf(id: string): Notices {
798	    let notices = this.notices.get(id);
799	    if (notices === undefined) {
800	      notices = { channelResult: "", channelResultAt: 0, settledRole: "", stolen: "", goldChange: 0, settledAt: 0, settledChoice: "", choiceDeadline: 0 };
801	      this.notices.set(id, notices);
802	    }
803	    return notices;
804	  }
805	
806	  /** Each newly settled ledger duel, in its players' notices: what was stolen and the gold that moved. */
807	  private noteSettlements(): void {
808	    for (const duel of this.ledger.duels) {
809	      if (duel.phase !== "settled" || this.noticed.has(duel.id)) continue;
810	      this.noticed.add(duel.id);
811	      this.noteSettlement(duel);
812	    }
813	  }
814	
815	  private noteSettlement(duel: LedgerDuel): void {
816	    const settlement = duel.settlement!;
817	    const result = duel.result!;
818	    for (const id of duel.players) {
819	      const notice = this.noticesOf(id);
820	      notice.settledAt = settlement.tick;
821	      notice.stolen = settlement.stolenType ?? "";
822	      notice.settledChoice = settlement.choice;
823	      notice.choiceDeadline = duel.choiceDeadline ?? 0;
824	      if (result.outcome !== "win") {
825	        notice.settledRole = "draw";
826	        notice.goldChange = 0;
827	      } else {
828	        const winner = result.winner === id;
829	        notice.settledRole = winner ? "winner" : "loser";
830	        notice.goldChange = winner ? settlement.gold : -settlement.gold;
831	      }
832	    }
833	  }
834	
835	  /**
836	   * After every world tick in development and tests: the ledger's own invariant, and the room's: every player the
837	   * ledger counts in the match has a ship, and every ship belongs to such a player.
838	   */
839	  private checkInvariants(tick: number): void {
840	    if (!this.tuning.checkInvariants) return;
841	    const problems = checkLedger(this.ledger);
842	    const ships = new Set(this.simulation.ships.map((ship) => ship.id));
843	    for (const player of this.ledger.players) {
844	      if (player.status !== "left" && !ships.has(player.id)) problems.push(`player ${player.id} is in the ledger's match without a ship`);
845	    }
846	    for (const id of ships) {
847	      const player = findPlayer(this.ledger, id);
848	      if (player === undefined || player.status === "left") problems.push(`ship ${id} has no player in the ledger's match`);
849	    }
850	    if (problems.length === 0) return;
851	    for (const problem of problems) this.violations.push(`tick ${tick}: ${problem}`);
852	    console.error(`match ${this.state.code} invariant violated at tick ${tick}: ${problems.join("; ")}`);
853	  }
854	
855	  /** Copies the plain simulation state into the synced schema, then updates what each client may see. */
856	  private mirror(): void {
857	    this.state.frame = this.simulation.frame;
858	    this.state.worldTick = this.simulation.worldTick;
859	    this.state.players = this.simulation.ships.length;
860	    const present = new Set<string>();
861	    for (const ship of this.simulation.ships) {
862	      present.add(ship.id);
863	      let synced = this.state.ships.get(ship.id);
864	      if (synced === undefined) {
865	        synced = new ShipSchema();
866	        synced.id = ship.id;
867	        synced.slot = ship.slot;
868	        this.state.ships.set(ship.id, synced);
869	      }
870	      synced.x = ship.x;
871	      synced.y = ship.y;
872	      synced.heading = ship.heading;
873	      synced.speed = ship.speed;
874	      synced.dock = ship.dock;
875	    }
876	    for (const id of [...this.state.ships.keys()]) if (!present.has(id)) this.state.ships.delete(id);
877	    this.mirrorEncounters(present);
878	    this.mirrorObjectives(present);
879	    this.updateViews();
880	  }
881	
882	  /** The rules' telegraphs and each player's status into the synced state (markers change only on events). */
883	  private mirrorEncounters(present: ReadonlySet<string>): void {
884	    const keys = new Set<string>();
885	    for (const attempt of this.encounters.attempts) {
886	      for (const [key, defenderId] of [
887	        [attempt.attackerId, attempt.defenderId],
888	        [attempt.attackerId + BLANK_GRAPPLE_SUFFIX, ""],
889	      ] as const) {
890	        keys.add(key);
891	        let synced = this.state.grapples.get(key);
892	        if (synced === undefined) {
893	          synced = new GrappleSchema();
894	          synced.attackerId = attempt.attackerId;
895	          this.state.grapples.set(key, synced);
896	        }
897	        synced.defenderId = defenderId;
898	        synced.aim = attempt.aim;
899	        synced.startTick = attempt.startTick;
900	        synced.landTick = attempt.landTick;
901	      }
902	    }
903	    for (const key of [...this.state.grapples.keys()]) if (!keys.has(key)) this.state.grapples.delete(key);
904	
905	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
906	    for (const id of present) {
907	      let status = this.state.status.get(id);
908	      if (status === undefined) {
909	        status = new PlayerStatusSchema();
910	        this.state.status.set(id, status);
911	      }
912	      const record = records.get(id);
913	      status.mode = record?.respawn != null ? "respawning" : duelOf(this.encounters, id) !== undefined ? "duel" : "sea";
914	      status.protection = record?.protection?.source ?? "";
915	      status.protectedUntil = record?.protection?.endTick ?? 0;
916	      status.cooldownUntil = record?.cooldownEndTick ?? 0;
917	      status.respawnAt = record?.respawn?.respawnTick ?? 0;
918	    }
919	    for (const id of [...this.state.status.keys()]) if (!present.has(id)) this.state.status.delete(id);
920	  }
921	
922	  /**
923	   * The ledger into the synced state: each player's private status (gold, rubbings, what their island and dock hold
924	   * while moored there, E's target and progress, their theft choice and their last results), and a contentless marker
925	   * for each recovery cache.
926	   */
927	  private mirrorObjectives(present: ReadonlySet<string>): void {
928	    const map = this.config.map;
929	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
930	    const held = this.heldPlayers();
931	    for (const id of present) {
932	      const status = this.state.status.get(id)!;
933	      const player = findPlayer(this.ledger, id);
934	      const ship = ships.get(id)!;
935	      const moored = ship.dock !== NOT_DOCKED && !held.has(id) && player !== undefined;
936	      status.gold = player?.gold ?? 0;
937	      status.rubbings = player === undefined ? "" : heldTypes(this.ledger, id).join(",");
938	      status.islandTypes = moored ? sealedTypesAt(this.ledger, map.docks[ship.dock]!.island).join(",") : "";
939	      status.cacheTypes = moored ? cachedTypesAt(this.ledger, map, ship.dock).join(",") : "";
940	      const target = moored && player.status === "connected" ? interactTarget(this.ledger, map, id, ship.dock) : undefined;
941	      status.target = target === undefined ? "" : `${target.kind}:${target.type}`;
942	      const channel = player?.channel ?? null;
943	      status.channel = channel?.kind ?? "";
944	      status.channelType = channel === null ? "" : (this.ledger.rubbings.find((rubbing) => rubbing.id === channel.rubbingId)?.type ?? "");
945	      status.channelHeld = channel?.heldTicks ?? 0;
946	      status.channelTotal = channel === null ? 0 : channel.kind === "collect" ? this.ledger.rules.collectTicks : this.ledger.rules.cacheClaimTicks;
947	      const choosing = this.ledger.duels.find((duel) => duel.phase === "choosing" && duel.result?.winner === id);
948	      const options = choosing === undefined ? [] : eligibleTheftTypes(this.ledger, choosing.id);
949	      status.theftDuel = choosing === undefined || options.length === 0 ? "" : (this.seaDuels.get(choosing.id)?.key ?? "");
950	      status.theftOptions = status.theftDuel === "" ? "" : options.join(",");
951	      status.theftDeadline = status.theftDuel === "" ? 0 : choosing!.choiceDeadline!;
952	      const notice = this.noticesOf(id);
953	      status.channelResult = notice.channelResult;
954	      status.channelResultAt = notice.channelResultAt;
955	      status.settledRole = notice.settledRole;
956	      status.stolen = notice.stolen;
957	      status.goldChange = notice.goldChange;
958	      status.settledAt = notice.settledAt;
959	      status.settledChoice = notice.settledChoice;
960	      status.choiceDeadline = notice.choiceDeadline;
961	    }
962	    const caches = new Set<string>();
963	    for (const cache of this.ledger.caches) {
964	      if (cacheRubbings(this.ledger, cache.id).length === 0) continue;
965	      caches.add(cache.id);
966	      let synced = this.state.caches.get(cache.id);
967	      if (synced === undefined) {
968	        synced = new CacheMarkerSchema();
969	        synced.x = cache.x;
970	        synced.y = cache.y;
971	        synced.dock = cacheDock(map, cache);
972	        this.state.caches.set(cache.id, synced);
973	      }
974	    }
975	    for (const id of [...this.state.caches.keys()]) if (!caches.has(id)) this.state.caches.delete(id);
976	  }
977	
978	  /**
979	   * Each client's view (§3, §6, §12, §16): its own ship unless it waits to respawn, the ships it can see that are not
980	   * in a duel or waiting to respawn, the grapples whose attacker it sees or that aim at it (with the target blanked
981	   * unless it sees the target too), the duel markers and caches in its sight, its own status and its own duel. A
982	   * fighter or a player waiting to respawn sees no other ship, grapple, marker or cache. Nothing else is encoded for it.
983	   */
984	  private updateViews(): void {
985	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
986	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
987	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
988	    for (const client of this.clients) {
989	      const view = client.view;
990	      if (view === undefined) continue;
991	      const self = client.sessionId;
992	      const viewer = ships.get(self);
993	      const away = inDuel.has(self) || respawning.has(self);
994	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
995	        const shown = view.has(item);
996	        if (visible && !shown) view.add(item);
997	        else if (!visible && shown) view.remove(item);
998	      };
999	      const visible = visibleShipIds(this.config, this.simulation, self);
1000	      for (const [id, ship] of this.state.ships) {
1001	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
1002	      }
1003	      const sees = (id: string) => {
1004	        const other = ships.get(id);
1005	        return !away && viewer !== undefined && other !== undefined && canSee(this.config, viewer, other);
1006	      };
1007	      for (const attempt of this.encounters.attempts) {
1008	        const aimedAt = attempt.attackerId === self || attempt.defenderId === self;
1009	        const full = aimedAt || (sees(attempt.attackerId) && sees(attempt.defenderId));
1010	        const blank = !full && sees(attempt.attackerId);
1011	        const fullEntry = this.state.grapples.get(attempt.attackerId);
1012	        const blankEntry = this.state.grapples.get(attempt.attackerId + BLANK_GRAPPLE_SUFFIX);
1013	        if (fullEntry !== undefined) sync(fullEntry, full);
1014	        if (blankEntry !== undefined) sync(blankEntry, blank);
1015	      }
1016	      for (const marker of this.state.markers.values()) sync(marker, !away && viewer !== undefined && pointInSight(this.config, viewer, marker));
1017	      for (const cache of this.state.caches.values()) sync(cache, !away && viewer !== undefined && pointInSight(this.config, viewer, cache));
1018	      for (const [id, status] of this.state.status) sync(status, id === self);
1019	      for (const lobby of this.state.duels.values()) sync(lobby, lobby.seats.some((seat) => seat.sessionId === self));
1020	    }
1021	  }
1022	
1023	  private async allocateCode(): Promise<string> {
1024	    for (let attempt = 0; attempt < 16; attempt++) {
1025	      const code = generateMatchCode();
1026	      const taken = await matchMaker.query({ name: this.roomName, code });
1027	      if (taken.length === 0) return code;
1028	    }
1029	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a match code");
1030	  }
1031	}
