1	import { matchMaker } from "colyseus";
2	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
3	import { isNavigable, seaMap } from "@pirate-sea-race/content";
4	import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
5	import { Buttons, MessageType, PROTOCOL_VERSION, TEST_PLACEMENT_PATH } from "@pirate-sea-race/protocol";
6	import { MatchRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
7	import { findPlayer } from "@pirate-sea-race/simulation/objectives";
8	import { AHEAD, HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
9	import { expectRoomChecks } from "./seaDuelSetup.js";
10	
11	let server: RunningGameServer;
12	let endpoint: string;
13	const clients: HeadlessClient[] = [];
14	
15	/**
16	 * An open stretch of sea: the row three tiles south of the hub, which the map keeps clear of land and shoals for 20
17	 * tiles east and west of the hub (checked below).
18	 */
19	const OPEN_ROW = seaMap.hub.tileY + 3;
20	const HUB_X = seaMap.hub.tileX;
21	const OPEN_REACH = 20;
22	
23	/** The match rooms this test's clients joined: checked after it, like `tracker`'s (`expectRoomChecks`). */
24	const rooms = new Set<MatchRoom>();
25	
26	async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
27	  const joined = await client;
28	  clients.push(joined);
29	  rooms.add(matchMaker.getLocalRoomById(joined.room.roomId) as unknown as MatchRoom);
30	  return joined;
31	}
32	
33	beforeAll(async () => {
34	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true });
35	  endpoint = `http://127.0.0.1:${server.port}`;
36	});
37	
38	afterEach(async () => {
39	  const checked = [...rooms];
40	  rooms.clear();
41	  await Promise.all(clients.splice(0).map((client) => client.leave()));
42	  await sleep(150);
43	  for (const room of checked) expectRoomChecks(room);
44	});
45	
46	afterAll(async () => {
47	  await server.close();
48	});
49	
50	function roomOf(client: HeadlessClient): MatchRoom {
51	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
52	}
53	
54	describe("test sea", () => {
55	  it("keeps the open row clear for a hull from 20 tiles west of the hub to 20 tiles east", () => {
56	    const [west, east] = [tileCentre(defaultSimulationConfig, HUB_X - OPEN_REACH, OPEN_ROW), tileCentre(defaultSimulationConfig, HUB_X + OPEN_REACH, OPEN_ROW)];
57	    expect(hullPathIsClear(defaultSimulationConfig, west.x, west.y, east.x, east.y)).toBe(true);
58	    // And the rows the tests put a second ship on.
59	    for (const row of [OPEN_ROW + 3, OPEN_ROW + 4]) expect(isNavigable(seaMap, HUB_X - 6, row)).toBe(true);
60	  });
61	});
62	
63	describe("private match", () => {
64	  it("creates a custom match with a six-character code", async () => {
65	    const host = await track(HeadlessClient.create(endpoint));
66	    expect(host.code).toMatch(/^[A-Z0-9]{6}$/);
67	    expect(host.room.state.custom).toBe(true);
68	    expect(host.room.state.protocolVersion).toBe(PROTOCOL_VERSION);
69	    expect(host.playerCount).toBe(1);
70	    expect(host.ship()).toMatchObject({ speed: 0, dock: -1 });
71	  });
72	
73	  it("lets two clients in sight of each other see the same authoritative sailing", async () => {
74	    const host = await track(HeadlessClient.create(endpoint));
75	    const guest = await track(HeadlessClient.join(endpoint, host.code.toLowerCase()));
76	    expect(guest.room.roomId).toBe(host.room.roomId);
77	    await host.waitFor(() => host.playerCount === 2);
78	    await host.placeShip(endpoint, { tileX: HUB_X - 6, tileY: OPEN_ROW, heading: 0 });
79	    await guest.placeShip(endpoint, { tileX: HUB_X - 6, tileY: OPEN_ROW + 4, heading: 0 });
80	    await guest.waitFor(() => guest.ship(host.sessionId) !== undefined);
81	
82	    const start = host.ship()!;
83	    expect(guest.ship(host.sessionId)).toEqual(start);
84	    const guestStart = guest.ship()!;
85	
86	    // Full ahead along heading 0 (east): the ship accelerates east and keeps its row.
87	    await host.hold(AHEAD, 600);
88	    await host.waitFor(() => host.ship()!.x > start.x);
89	    expect(host.ship()!.y).toBe(start.y);
90	
91	    // Both clients converge on the same server-decided position once the ship has coasted to a stop.
92	    await host.waitFor(() => host.ship()!.speed === 0, 5000);
93	    const settled = host.ship()!;
94	    await guest.waitFor(() => guest.ship(host.sessionId)?.x === settled.x);
95	    expect(guest.ship(host.sessionId)).toEqual(settled);
96	    expect(settled.x).toBeGreaterThan(start.x);
97	    // The guest sent nothing, so its ship has not moved.
98	    expect(guest.ship()).toEqual(guestStart);
99	    expect(host.ship(guest.sessionId)).toEqual(guestStart);
100	  });
101	
102	  it("removes a ship when its player leaves", async () => {
103	    const host = await track(HeadlessClient.create(endpoint));
104	    const guest = await HeadlessClient.join(endpoint, host.code);
105	    await host.waitFor(() => host.playerCount === 2);
106	    await guest.placeShip(endpoint, { tileX: HUB_X - 6, tileY: OPEN_ROW, heading: 0 });
107	    await host.placeShip(endpoint, { tileX: HUB_X - 4, tileY: OPEN_ROW, heading: 0 });
108	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
